def create_seed(path: Path):
    path.parent.mkdir(parents=True, exist_ok=True)
    if path.exists():
        return
    with path.open('w', encoding='utf-8-sig', newline='') as f:
        writer = csv.DictWriter(f, fieldnames=['text', 'label', 'scenario_group', 'source'])
        writer.writeheader()
        for i, pair in enumerate(SCENARIOS):
            for sentence in pair:
                writer.writerow(dict(text=sentence, label=LABELS[i // 12], scenario_group=f'synthetic-{i:03}', source='Синтетический учебный пример'))

